package com.example.starter.audit.model;

/**
 * 任务绑定的不可变版本集合，任一版本均为必填。
 *
 * @param codeVersion   代码版本（提交哈希或版本标签）
 * @param configVersion 配置版本或内容摘要
 * @param mapVersion    地图版本或内容摘要
 * @param rosbagVersion 输入 rosbag 版本或内容摘要
 * @param seed          随机种子，保证相同绑定时可确定性重放
 */
public record Bindings(
        String codeVersion,
        String configVersion,
        String mapVersion,
        String rosbagVersion,
        long seed
) {
}

package com.example.starter.audit.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 创建任务请求。
 *
 * @param requestId     幂等键，同键同参重放原结果，同键异参返回 409
 * @param codeVersion   代码版本（必填）
 * @param configVersion 配置版本（必填）
 * @param mapVersion    地图版本（必填）
 * @param rosbagVersion 输入 rosbag 版本（必填）
 * @param seed          随机种子（必填）
 */
public record CreateTaskRequest(
        String requestId,
        @NotBlank String codeVersion,
        @NotBlank String configVersion,
        @NotBlank String mapVersion,
        @NotBlank String rosbagVersion,
        @NotNull Long seed
) {
}

package com.example.starter.audit.web;

import org.springframework.http.HttpStatus;

/**
 * 携带 HTTP 状态码的业务异常。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus getStatus() {
        return status;
    }
}

