package com.example.starter.audit.domain;

import com.example.starter.audit.model.Bindings;
import com.example.starter.audit.model.Stage;

/**
 * 阶段执行上下文，向可注入的阶段执行器提供绑定版本与上游产物摘要。
 */
public record StageContext(
        long taskId,
        Stage stage,
        Bindings bindings,
        String upstreamDigest,
        int attempt
) {
}

package com.example.starter.audit.domain;

import java.util.Map;

/**
 * 单个阶段的确定性产物：关键指标、合成产物字节与可重放命令。
 * 产物相对路径与 SHA-256 由编排层统一计算并落库。
 */
public record StageProduct(
        Map<String, Double> metrics,
        byte[] artifactBytes,
        String replayCommand
) {
}

package com.example.starter.audit.domain;

/**
 * 阶段业务失败（非中断），编排层将阶段与任务置为 FAILED。
 */
public class StageFailureException extends Exception {

    public StageFailureException(String message) {
        super(message);
    }
}

package com.example.starter.audit.domain;

/**
 * 阶段执行过程中收到中断信号，编排层将阶段与任务置为 INTERRUPTED。
 */
public class StageInterruptedException extends Exception {

    public StageInterruptedException(String message) {
        super(message);
    }
}

package com.example.starter.audit.domain;

/**
 * 可注入的阶段执行器：模拟感知、定位、规划、控制，不依赖真实自动驾驶栈。
 * 实现必须保证相同绑定版本、随机种子与上游产物摘要下输出确定。
 */
public interface StageExecutor {

    /**
     * 执行单个阶段。
     *
     * @param context 阶段上下文（绑定版本、种子、上游摘要等）
     * @return 阶段产物（指标、合成产物、可重放命令）
     */
    StageProduct execute(StageContext context)
            throws StageFailureException, StageInterruptedException;
}

